choose.when:
AND EXISTS (
    SELECT 1
    FROM class_counselor_relation scope_ccr
    WHERE scope_ccr.class_id = su.class_id
      AND scope_ccr.counselor_id = #{scope.teacherId}
)

AND EXISTS (
    SELECT 1
    FROM class_counselor_relation scope_ccr
    WHERE scope_ccr.class_id = c.id
      AND scope_ccr.counselor_id = #{scope.teacherId}
)

mapper.select:
SELECT su.id AS student_id, su.student_user_id AS student_number, su.name AS student_name, su.class_id, c.name AS class_name, m.name AS major_name, CASE WHEN ias.status = 'SUBMITTED' THEN 'SUBMITTED' ELSE 'NOT_SUBMITTED' END AS submission_status, CASE WHEN ias.status = 'SUBMITTED' THEN ias.submitted_at ELSE NULL END AS submitted_at, CASE WHEN ias.status = 'SUBMITTED' THEN (SELECT COUNT(*) FROM internship_appraisal_file iaf WHERE iaf.submission_id = ias.id) ELSE 0 END AS file_count, CASE WHEN ias.status = 'SUBMITTED' THEN ias.id ELSE NULL END AS submission_id FROM student_users su LEFT JOIN `class` c ON c.id = su.class_id LEFT JOIN major m ON m.id = su.major_id
WHERE 1 = 1
ORDER BY CASE WHEN ias.status = 'SUBMITTED' THEN 0 ELSE 1 END, ias.submitted_at DESC, su.student_user_id ASC, su.id ASC LIMIT #{offset}, #{pageSize}
